insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'In therapeutic drug monitoring, a trough level is collected:', '["At the time of peak absorption","Immediately before the next dose","Exactly 1 hour after an IV dose","At any random time"]'::jsonb, 1, 'The trough is the lowest concentration, reached just before the next dose; the peak reflects maximum absorption. Reference: Overview of Therapeutic Drug Monitoring (pmc.ncbi.nlm.nih.gov/articles/PMC2687654).', 1, 'verified'
