insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Carbon monoxide is toxic mainly because it:', '["Oxidizes heme iron to the ferric state","Binds hemoglobin about 200–250 times more strongly than oxygen","Inhibits acetylcholinesterase","Lyses red blood cells"]'::jsonb, 1, 'CO forms carboxyhemoglobin, which cannot carry oxygen. Oxidized (ferric) heme iron is methemoglobin, and acetylcholinesterase inhibition is the mechanism of organophosphates. Reference: StatPearls, Carbon Monoxide Poisoning (ncbi.nlm.nih.gov/books/NBK557888).', 1, 'verified'
