select null, t.id, 'builtin', 'The reagent strip test for urine protein is based on the principle of:', '["Diazo reaction","Protein error of indicators","Pseudoperoxidase activity","Sodium nitroprusside reaction"]'::jsonb, 1, 'The protein pad uses the protein error of indicators (e.g. tetrabromophenol blue). Diazo = bilirubin, pseudoperoxidase = blood, nitroprusside = ketones. Reference: Wikipedia, Urine test strip, Protein testing (en.wikipedia.org/wiki/Urine_test_strip).', 1, 'verified'
