select null, t.id, 'builtin', 'Which urine crystal is described as having a ''coffin-lid'' shape?', '["Calcium oxalate","Uric acid","Triple phosphate","Cystine"]'::jsonb, 2, 'Triple phosphate (ammonium magnesium phosphate) crystals look like coffin lids and are seen in alkaline urine. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AAFP 2005 (aafp.org/afp/2005/0315/p1153).', 1, 'verified'
