insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Cystine crystals in urine appear as:', '["Colorless hexagonal plates","Envelope-shaped octahedrons","Fine needles in sheaves","Yellow-brown spheres with concentric striations"]'::jsonb, 0, 'Cystine forms colorless hexagonal plates in acidic urine. Envelope shapes = calcium oxalate dihydrate; needles = tyrosine; striated spheres = leucine. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AAFP 2005 (aafp.org/afp/2005/0315/p1153).', 2, 'verified'
