insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'The presence of WBC casts in urine is most suggestive of:', '["Acute glomerulonephritis","Pyelonephritis","Cystitis","Nephrotic syndrome"]'::jsonb, 1, 'WBC casts form in the tubules, so they point to infection or inflammation within the kidney: pyelonephritis (and also interstitial nephritis). Cystitis (bladder) gives WBCs but no casts; RBC casts suggest glomerulonephritis. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AAFP 2005 (aafp.org/afp/2005/0315/p1153).', 2, 'verified'
