insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Xanthochromia of cerebrospinal fluid refers to:', '["A cloudy appearance from many white cells","A yellowish color, mainly from bilirubin after bleeding into the CSF","A clot that forms in the collection tube","A greenish color from bacterial pigment"]'::jsonb, 1, 'Xanthochromia is yellow CSF from bilirubin as red cells break down; it is best seen 6–12 hours after a bleed and supports subarachnoid hemorrhage, though it is not specific for it. Reference: StatPearls, Xanthochromia (ncbi.nlm.nih.gov/books/NBK526048).', 2, 'verified'
