insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Needle-shaped, negatively birefringent crystals in synovial fluid indicate:', '["Pseudogout (calcium pyrophosphate)","Gout (monosodium urate)","Septic arthritis","Cholesterol crystal effusion"]'::jsonb, 1, 'Monosodium urate crystals of gout are needle-shaped and negatively birefringent under polarized light; finding them is the gold standard for diagnosis. CPPD crystals of pseudogout are positively birefringent. Reference: StatPearls, Gout (ncbi.nlm.nih.gov/books/NBK546606) and Monoarticular Arthritis (ncbi.nlm.nih.gov/books/NBK542164).', 1, 'verified'
