insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'The guaiac fecal occult blood test detects blood through:', '["Antibodies against human globin","The pseudoperoxidase activity of heme","Oxidation of bilirubin","Prussian blue staining of iron"]'::jsonb, 1, 'Heme''s pseudoperoxidase activity releases oxygen from hydrogen peroxide, which oxidizes the guaiac chromogen. The fecal immunochemical test (FIT) uses antibodies to human globin instead. Reference: StatPearls, Fecal Occult Blood Test (ncbi.nlm.nih.gov/books/NBK537138).', 1, 'verified'
