insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Compared with guaiac testing, the fecal immunochemical test (FIT):', '["Reacts with any peroxidase, including plant peroxidases","Is specific for human globin and needs no dietary restriction","Does not need a stool sample","Also measures fecal fat"]'::jsonb, 1, 'FIT targets human globin with antibodies, so food peroxidases don''t interfere and no diet restriction is needed; it is also more sensitive for colorectal cancer. Reference: Guaiac-based faecal occult blood tests versus faecal immunochemical tests, Cochrane review (pmc.ncbi.nlm.nih.gov/articles/PMC9169237).', 2, 'verified'
