insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'A urine specific gravity that stays fixed at about 1.010 (isosthenuria) suggests:', '["Dehydration","Loss of the kidney''s concentrating ability","Diabetes mellitus","Normal kidney function"]'::jsonb, 1, 'In intrinsic renal insufficiency the specific gravity is fixed at 1.010, the specific gravity of the glomerular filtrate. Normal values range from 1.003 to 1.030. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AAFP 2005 (aafp.org/afp/2005/0315/p1153).', 2, 'verified'
