insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Cloudy urine is most often caused by:', '["Bilirubin","Precipitated phosphate crystals in alkaline urine (or pyuria)","Ketones","Glucose"]'::jsonb, 1, 'Cloudy urine is often from phosphate crystals that precipitate in alkaline urine, but pus (pyuria) can also cause it. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AAFP 2005 (aafp.org/afp/2005/0315/p1153).', 1, 'verified'
