select null, t.id, 'builtin', 'Hemophilia A is caused by a deficiency of which coagulation factor?', '["Factor IX","Factor VIII","Factor XI","Factor XII"]'::jsonb, 1, 'Hemophilia A is an X-linked deficiency of Factor VIII. Hemophilia B (Christmas disease) is a Factor IX deficiency. Reference: StatPearls, Bleeding Disorders (ncbi.nlm.nih.gov/books/NBK541050) and Hemophilia B (ncbi.nlm.nih.gov/books/NBK560792).', 1, 'verified'
