insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Which formula is used to compute the mean corpuscular volume (MCV) in fL?', '["(Hgb in g/dL ÷ RBC count) × 10","(Hct in % ÷ RBC count) × 10","(Hgb in g/dL ÷ Hct in %) × 100","(RBC count ÷ Hct in %) × 10"]'::jsonb, 1, 'MCV = (Hct ÷ RBC count in millions/µL) × 10. Hgb ÷ RBC × 10 is MCH, and Hgb ÷ Hct × 100 is MCHC. Reference: StatPearls, Mean Corpuscular Volume (ncbi.nlm.nih.gov/books/NBK545275).', 1, 'verified'
