select null, t.id, 'builtin', 'Auer rods in blast cells are most characteristic of:', '["Acute lymphoblastic leukemia","Chronic lymphocytic leukemia","Acute myeloid leukemia","Hairy cell leukemia"]'::jsonb, 2, 'Auer rods are fused primary (azurophilic) granules found in myeloid blasts, so they point to AML rather than lymphoid leukemias. Reference: StatPearls, Laboratory Evaluation of Acute Leukemia (ncbi.nlm.nih.gov/books/NBK611988).', 2, 'verified'
