insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Which iron profile is typical of iron deficiency anemia?', '["High ferritin, low TIBC","Low serum iron, high TIBC, low ferritin","Normal serum iron, TIBC, and ferritin","Low serum iron, low TIBC, high ferritin"]'::jsonb, 1, 'Iron deficiency gives low serum iron, high TIBC, and low ferritin, with microcytic, hypochromic cells. Anemia of chronic disease has a high ferritin, and thalassemia has normal iron studies. Ferritin is an acute-phase reactant, so inflammation can hide a low value. Reference: StatPearls, Chronic Anemia (ncbi.nlm.nih.gov/books/NBK568790) and Iron Deficiency and Microcytic Hypochromic Anemia (ncbi.nlm.nih.gov/books/NBK560876).', 1, 'verified'
