select null, t.id, 'builtin', 'In a healthy adult, red blood cells are produced in the:', '["Yolk sac","Liver","Spleen","Bone marrow"]'::jsonb, 3, 'Hematopoiesis starts in the yolk sac, shifts to the fetal liver (and spleen), and the bone marrow takes over near the end of gestation. In adults it normally occurs only in the bone marrow. Reference: StatPearls, Embryology, Hematopoiesis (ncbi.nlm.nih.gov/books/NBK544245).', 1, 'verified'
