select null, t.id, 'builtin', 'Reticular fibers (type III collagen) are best shown with:', '["Silver stains, which show the fibers as black","Routine hematoxylin","Congo red","Oil Red O"]'::jsonb, 0, 'The reticulin stain uses silver impregnation to show reticulin fibers, which are made of type III collagen; the fibers appear black. Reference: Krishna, Role of special stains in diagnostic liver pathology, Clin Liver Dis 2013 (pmc.ncbi.nlm.nih.gov/articles/PMC6448668).', 1, 'verified'
