insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'In H&E staining, "bluing" is done by:', '["Dipping the slide in eosin","Heating the slide","Rinsing in mildly alkaline water after hematoxylin","Rinsing in xylene"]'::jsonb, 2, 'Routine H&E runs hematoxylin, water wash, differentiation (removes excess hematoxylin), bluing, then eosin. The bluing reagent is a weakly alkaline solution that turns the nuclei blue. References: Ma et al., Rapid vs routine H&E staining of frozen breast sections, J Int Med Res 2024 (pmc.ncbi.nlm.nih.gov/articles/PMC11184997); Rowley et al., J Histochem Cytochem 2020 (pmc.ncbi.nlm.nih.gov/articles/PMC6931168).', 2, 'verified'
