insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Alcian blue staining at pH 1.0 is mainly used to detect:', '["Glycogen","Sulfated mucins (sulfomucins)","Cell nuclei","Neutral lipids"]'::jsonb, 1, 'Alcian blue at pH 1.0 is the usual stain for sulfomucins; at pH 2.5 it also stains sialylated (carboxylated) mucins. Some pH 1.0 protocols can give false positives from sialomucins. Reference: Padra & Lindén, Optimization of Alcian blue pH 1.0 histo-staining protocols, Glycobiology 2021 (pmc.ncbi.nlm.nih.gov/articles/PMC8881734).', 3, 'verified'
