insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'The classic Papanicolaou stain uses:', '["Five stains in three solutions","Two stains in one solution","One silver stain","Three stains in five solutions"]'::jsonb, 0, 'The classic Pap stain is a five-dye method: hematoxylin for nuclei, then Orange G and EA as cytoplasmic counterstains, given in three solutions. References: Chantziantoniou et al., Inception and Development of the Papanicolaou Stain Method, Acta Cytol 2017 (doi.org/10.1159/000457827); Wikipedia, Papanicolaou stain (en.wikipedia.org/wiki/Papanicolaou_stain).', 2, 'verified'
