insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'The EA solution of the Pap stain contains:', '["Hematoxylin and alum","Orange G only","Crystal violet and safranin","Eosin Y, light green SF yellowish, and Bismarck brown Y"]'::jsonb, 3, 'The EA counterstain contains light green, Bismarck brown, and eosin. Orange G is a separate solution. Reference: Chantziantoniou et al., Inception and Development of the Papanicolaou Stain Method, Acta Cytol 2017 (doi.org/10.1159/000457827).', 3, 'verified'
