insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'In a Pap-stained cervical smear, intermediate and parabasal cells usually appear:', '["Orange to pink","Black","Green","Bright red"]'::jsonb, 2, 'With the Pap stain, nuclei are blue (hematoxylin). Most superficial cells have delicate pink cytoplasm, while intermediate cells have pale green and parabasal cells dense green cytoplasm. Reference: Kamal, Nonneoplastic Cervical Cytology, CytoJournal 2022 (pmc.ncbi.nlm.nih.gov/articles/PMC9063585).', 2, 'verified'
