insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'For a Pap test, cells are collected from:', '["The posterior vaginal wall only","The transformation zone, where squamous cells meet glandular endocervical cells","The endometrial cavity","The surface of the ovary"]'::jsonb, 1, 'The Pap test collects cells at the outer opening of the cervix at the transformation zone, where the outer squamous cells meet the inner glandular endocervical cells. Reference: Wikipedia, Pap test (en.wikipedia.org/wiki/Pap_test).', 1, 'verified'
