insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'LSIL on a Pap smear usually indicates:', '["Invasive carcinoma","Normal cells","Mild dysplasia (CIN 1), usually from HPV infection","Carcinoma in situ"]'::jsonb, 2, 'LSIL changes on a Pap test are generally CIN 1 and are usually caused by HPV infection. HSIL can be CIN 2 or CIN 3. Reference: National Cancer Institute, HPV and Pap Test Results: Next Steps (cancer.gov/types/cervical/understanding-abnormal-hpv-and-pap-test-results).', 2, 'verified'
