insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'A squamous cell with a clear perinuclear halo and an enlarged, dark nucleus (a koilocyte) is caused by:', '["Candida albicans","Human papillomavirus (HPV)","Trichomonas vaginalis","Gardnerella vaginalis"]'::jsonb, 1, 'Sharply outlined perinuclear clearing (koilocytosis) is the characteristic cytopathic effect of HPV. Halo-like clearing caused by Candida or Trichomonas should not be mistaken for it. References: Alrajjal et al., CytoJournal 2021 (pmc.ncbi.nlm.nih.gov/articles/PMC8326095); Misawa et al., Koilocytosis in LSIL Cytology, Pathogens 2026 (pmc.ncbi.nlm.nih.gov/articles/PMC13209615).', 1, 'verified'
