select null, t.id, 'builtin', 'How many Barr bodies are expected in a cell from a person with a 47,XXY karyotype?', '["1","0","2","3"]'::jsonb, 0, 'A Barr body is an inactive X chromosome, and the number of Barr bodies is always one fewer than the number of X chromosomes. Two X chromosomes give one Barr body. The buccal smear test was developed to look for them. Reference: Wikipedia, Barr body (en.wikipedia.org/wiki/Barr_body).', 2, 'verified'
