select null, t.id, 'builtin', 'Cells collected by fine-needle aspiration belong to which type of cytology?', '["Exfoliative cytology","Imprint cytology","Frozen section","Intervention cytology"]'::jsonb, 3, 'There are two ways to collect cells for cytopathology: exfoliative cytology (cells shed or scraped off, as in a Pap smear) and intervention cytology, where cells are taken by entering the tissue, as in fine-needle aspiration. Reference: Wikipedia, Cytopathology (en.wikipedia.org/wiki/Cytopathology).', 1, 'verified'
