select null, t.id, 'builtin', 'The penalty in Section 29 of RA 5527 for violating the Act is:', '["A fine of ₱2,000–₱5,000, or 6 months to 2 years in prison, or both","A fine of ₱500–₱1,000 only","6 to 12 years in prison","Closure of the hospital"]'::jsonb, 0, 'Section 29: a fine of not less than ₱2,000 nor more than ₱5,000, or imprisonment of six months to two years, or both, at the court''s discretion. Reference: RA 5527 full text (lawphil.net/statutes/repacts/ra1969/ra_5527_1969.html).', 2, 'verified'
