  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('High-temperature short-time (HTST) pasteurization of milk uses:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Plastic items such as gloves and IV tubing are commonly sterilized with:', '["Ultraviolet light","Ionizing radiation (e.g., gamma rays)","Boiling water","70% alcohol"]'::jsonb, 1, 'Ionizing radiation is used clinically to sterilize gloves, IV tubing, and other latex and plastic items. UV light is nonionizing and does not penetrate surfaces, plastics, or glass. Reference: OpenStax Microbiology, 13.2 Using Physical Methods to Control Microorganisms (openstax.org/books/microbiology/pages/13-2-using-physical-methods-to-control-microorganisms).', 1, 'verified'
