insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Why is 70% alcohol a better disinfectant than 100% alcohol?', '["100% alcohol is too flammable to use","Pure alcohol coagulates surface proteins too fast, blocking penetration into the cell","70% alcohol also kills endospores","100% alcohol evaporates too slowly"]'::jsonb, 1, 'Alcohols work better in water: at high concentrations they rapidly coagulate surface proteins, which prevents effective penetration of the cell. Reference: OpenStax Microbiology, 13.3 Using Chemicals to Control Microorganisms (openstax.org/books/microbiology/pages/13-3-using-chemicals-to-control-microorganisms).', 2, 'verified'
