insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Viruses are described as obligate intracellular parasites because they:', '["Can grow on any nutrient agar","Can only replicate inside a living host cell","Make their own ATP","Divide by binary fission"]'::jsonb, 1, 'Viruses are acellular and must infect a cellular host to survive and reproduce, which makes them obligate intracellular parasites. Reference: OpenStax Microbiology, 6.1 Viruses (openstax.org/books/microbiology/pages/6-1-viruses).', 1, 'verified'
