insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'In viral cell culture, a cytopathic effect (CPE) is:', '["A color change of the culture medium from bacterial growth","A visible abnormality of infected host cells","The antibody response of the patient","A clump of red cells caused by the virus"]'::jsonb, 1, 'Cytopathic effects are distinct, observable cell abnormalities due to viral infection; their type and severity depend on the virus. Reference: OpenStax Microbiology, 6.3 Isolation, Culture, and Identification of Viruses (openstax.org/books/microbiology/pages/6-3-isolation-culture-and-identification-of-viruses).', 1, 'verified'
