insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Which of these can be used to grow viruses in the laboratory?', '["Blood agar plates","Embryonated eggs","Sabouraud dextrose agar","Thioglycollate broth"]'::jsonb, 1, 'Viruses need a living host cell, so they are grown in whole organisms, cell cultures, or the embryo inside an embryonated bird''s egg, not on bacterial media. Reference: OpenStax Microbiology, 6.3 Isolation, Culture, and Identification of Viruses (openstax.org/books/microbiology/pages/6-3-isolation-culture-and-identification-of-viruses).', 1, 'verified'
