insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'The two main surface spike antigens of influenza virus are:', '["Hemagglutinin and neuraminidase","Fusion protein and nucleoprotein","Capsid and envelope","Reverse transcriptase and integrase"]'::jsonb, 0, 'Influenza''s main antigens are the spike proteins hemagglutinin (H) and neuraminidase (N); changes in them by antigenic drift and shift produce new strains. Reference: OpenStax Microbiology, 22.3 Viral Infections of the Respiratory Tract (openstax.org/books/microbiology/pages/22-3-viral-infections-of-the-respiratory-tract).', 1, 'verified'
