insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'A person is anti-HBs positive but HBsAg and anti-HBc negative. This means:', '["Acute hepatitis B infection","Chronic hepatitis B infection","Immunity from hepatitis B vaccination","Immunity from a past natural infection"]'::jsonb, 2, 'Anti-HBs alone means vaccine immunity. Past natural infection would also show anti-HBc, which vaccines do not produce. Reference: CDC, Interpretation of Hepatitis B Serologic Test Results (cdc.gov/hepatitis-b/media/serologicchartv8.pdf).', 2, 'verified'
