select null, t.id, 'builtin', 'HBsAg positive, total anti-HBc positive, and IgM anti-HBc positive, with anti-HBs negative, indicates:', '["Acute hepatitis B infection","Immunity from vaccination","Resolved past infection","Susceptible, never infected"]'::jsonb, 0, 'HBsAg with IgM anti-HBc means acute infection; the same pattern with IgM anti-HBc negative means chronic infection. Reference: CDC, Interpretation of Hepatitis B Serologic Test Results (cdc.gov/hepatitis-b/media/serologicchartv8.pdf).', 2, 'verified'
